package com.example.domain.model.i18n

internal object DuaBn3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("তোমার রহমতের আশা করি", "হে আল্লাহ! আমি তোমার রহমতের আশা করি, অতএব এক পলকের জন্যও আমাকে আমার নফসের হাতে ছেড়ে দিও না এবং আমার সব কাজ ঠিক করে দাও। তুমি ছাড়া কোনো ইলাহ নেই।", "বিপদগ্রস্তের দোয়া (দাওয়াতুল মাকরুব)।", "নবী ﷺ একে বিপদগ্রস্তের দোয়া বলেছেন।"),
        "dua_against_enemy_ahzab" to DuaText("শত্রুবাহিনীর বিরুদ্ধে", "হে আল্লাহ, কিতাব নাজিলকারী, দ্রুত হিসাব গ্রহণকারী! বাহিনীগুলোকে পরাজিত করো। হে আল্লাহ! তাদের পরাজিত করো এবং তাদের কাঁপিয়ে দাও।", "শত্রুর মোকাবেলায় — আহযাব যুদ্ধের দোয়া।", "শত্রুর বিরুদ্ধে নবী ﷺ-এর দোয়া।"),
        "dua_anta_adudi" to DuaText("তুমিই আমার সহায়", "হে আল্লাহ! তুমিই আমার বাহু ও সাহায্যকারী। তোমার সাহায্যেই আমি কৌশল করি, তোমার সাহায্যেই আক্রমণ করি এবং তোমার সাহায্যেই লড়াই করি।", "প্রতিযোগিতা বা বড় চ্যালেঞ্জের আগে।", "নবী ﷺ যুদ্ধের সময় এটি বলতেন।"),
        "dua_ikfinihim" to DuaText("তাদের বিরুদ্ধে আমার জন্য যথেষ্ট হও", "হে আল্লাহ! তুমি যেভাবে চাও তাদের বিরুদ্ধে আমার জন্য যথেষ্ট হয়ে যাও।", "জালিমদের অনিষ্ট থেকে — আসহাবুল উখদুদের কিশোরের দোয়া।", "আল্লাহ কিশোরকে জালিমদের থেকে রক্ষা করেন।"),
        "dua_qadarullah" to DuaText("খারাপ কিছু ঘটলে", "এটি আল্লাহর তাকদির, তিনি যা চেয়েছেন তা-ই করেছেন।", "অপছন্দনীয় কিছু ঘটলে 'যদি' বলার পরিবর্তে।", "'যদি' শয়তানের দরজা খুলে দেয়।"),
        "dua_ala_kulli_hal" to DuaText("সব অবস্থায় প্রশংসা", "সব অবস্থায় সকল প্রশংসা আল্লাহর।", "অপছন্দনীয় কিছু ঘটলে।", "নবী ﷺ অপছন্দনীয় বিষয়ে এটি বলতেন।"),
        "dua_dogs_barking" to DuaText("রাতে কুকুরের ডাক শুনলে", "আমি বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় চাই।", "রাতে কুকুরের ডাক বা গাধার ডাক শুনলে।", "তারা এমন কিছু দেখে যা তোমরা দেখো না।"),
        "dua_leaving_home_adilla" to DuaText("পথভ্রষ্টতা থেকে আশ্রয়", "হে আল্লাহ! আমি তোমার আশ্রয় চাই যেন আমি পথভ্রষ্ট না হই বা পথভ্রষ্ট না করা হই, পদস্খলিত না হই বা পদস্খলিত না করা হই, জুলুম না করি বা জুলুমের শিকার না হই, মূর্খতা না করি বা আমার সাথে মূর্খতা না করা হয়।", "ঘর থেকে বের হওয়ার সময় — উম্মে সালামা (রা.)-এর বর্ণনা।", "নবী ﷺ ঘর থেকে বের হলেই এটি পড়তেন।"),
        "dua_ascending_descending" to DuaText("ওঠা ও নামা", "আল্লাহ সবচেয়ে বড় (ওঠার সময়)। — আল্লাহ পবিত্র (নামার সময়)।", "সফরে উঁচুতে ওঠার সময় 'আল্লাহু আকবার', নামার সময় 'সুবহানাল্লাহ'।", "সফরে সাহাবিদের (রা.) আমল।"),
        "dua_traveller_sahar" to DuaText("ভোরের আগে মুসাফিরের দোয়া", "একজন শ্রোতা আল্লাহর প্রশংসা ও আমাদের প্রতি তাঁর উত্তম নিয়ামতের কথা (অন্যদের) শুনিয়ে দিল। হে আমাদের রব! আমাদের সঙ্গী হও এবং আমাদের প্রতি অনুগ্রহ করো — আগুন থেকে আল্লাহর আশ্রয় চেয়ে (এটি বলছি)।", "সফরে সাহরির সময়।", "নবী ﷺ সফরে সাহরির সময় এটি বলতেন।"),
        "dua_zawwadakallah" to DuaText("মুসাফিরকে: আল্লাহ তাকওয়ার পাথেয় দিন", "আল্লাহ তোমাকে তাকওয়ার পাথেয় দিন, তোমার গুনাহ ক্ষমা করুন এবং তুমি যেখানেই থাকো তোমার জন্য কল্যাণ সহজ করুন।", "মুসাফিরকে বিদায়ের সময়।", "নবী ﷺ সফরে যাত্রীকে এই দোয়া দিয়েছেন।"),
        "dua_traveller_to_resident" to DuaText("মুসাফিরের পরিবারের জন্য দোয়া", "আমি তোমাদের সেই আল্লাহর কাছে সোপর্দ করছি যাঁর কাছে গচ্ছিত জিনিস নষ্ট হয় না।", "সফরে যাত্রী পরিবারকে বিদায় দেওয়ার সময়।", "পরিবারের হেফাজত আল্লাহর কাছে সোপর্দ।"),
        "dua_entering_village" to DuaText("কোনো গ্রাম বা শহরে প্রবেশ", "হে আল্লাহ, সাত আসমান ও সেগুলো যা ছায়া দেয় তার রব, সাত জমিন ও সেগুলো যা বহন করে তার রব, শয়তানদের ও তারা যাদের পথভ্রষ্ট করে তাদের রব, বাতাস ও তা যা উড়িয়ে নেয় তার রব! আমরা তোমার কাছে এই জনপদের ও এর অধিবাসীদের কল্যাণ চাই, এবং এর, এর অধিবাসীদের ও এতে যা আছে তার অনিষ্ট থেকে তোমার আশ্রয় চাই।", "কোনো জনপদ/শহরে প্রবেশের আগে।", "নবী ﷺ কোনো জনপদে প্রবেশ করতে চাইলে এটি পড়তেন।"),
        "dua_vehicle_stumbles" to DuaText("বাহন হোঁচট খেলে", "আল্লাহর নামে।", "বাহন পিছলে গেলে বা হোঁচট খেলে 'শয়তান ধ্বংস হোক' বলার পরিবর্তে।", "বিসমিল্লাহ বললে শয়তান মাছির মতো ছোট হয়ে যায়।"),
        "dua_ajz_kasal_haram" to DuaText("অক্ষমতা ও বার্ধক্য থেকে আশ্রয়", "হে আল্লাহ! আমি তোমার আশ্রয় চাই অক্ষমতা ও অলসতা থেকে, কাপুরুষতা ও বার্ধক্য থেকে, জীবন ও মৃত্যুর ফিতনা থেকে এবং কবরের আজাব থেকে।", "দৈনিক আশ্রয়ের ব্যাপক দোয়া।", "নবী ﷺ-এর বেশি বেশি করা দোয়া।"),
        "dua_sharri_ma_amiltu" to DuaText("নিজের কাজের অনিষ্ট থেকে আশ্রয়", "হে আল্লাহ! আমি তোমার আশ্রয় চাই যে কাজ আমি করেছি তার অনিষ্ট থেকে এবং যা করিনি তার অনিষ্ট থেকে।", "আয়েশা (রা.)-এর বর্ণনামতে নবী ﷺ-এর দোয়া।", "করা ও না করা উভয়ের পরিণাম থেকে হেফাজত।"),
        "dua_jahdil_bala" to DuaText("কঠিন পরীক্ষা থেকে আশ্রয়", "হে আল্লাহ! আমি তোমার আশ্রয় চাই কঠিন পরীক্ষা থেকে, দুর্ভাগ্যের কবলে পড়া থেকে, মন্দ ফয়সালা থেকে এবং শত্রুদের উপহাস থেকে।", "কঠিন পরীক্ষা ও শত্রুর আনন্দ থেকে আশ্রয়।", "নবী ﷺ এই চারটি বিষয় থেকে আশ্রয় চাইতেন।"),
        "dua_fitnat_ghina_faqr" to DuaText("ধন ও দারিদ্র্যের ফিতনা থেকে আশ্রয়", "হে আল্লাহ! আমি তোমার আশ্রয় চাই অলসতা ও বার্ধক্য থেকে, গুনাহ ও ঋণ থেকে, কবরের ফিতনা ও আজাব থেকে, আগুনের ফিতনা ও আজাব থেকে, ধনসম্পদের ফিতনার অনিষ্ট থেকে এবং দারিদ্র্যের ফিতনা থেকে।", "কবর, জাহান্নাম, ধন ও দারিদ্র্যের ফিতনা থেকে আশ্রয় (দোয়ার অংশ)।", "নবী ﷺ-এর ব্যাপক আশ্রয়ের দোয়া।"),
        "dua_kufr_faqr" to DuaText("কুফর ও দারিদ্র্য থেকে আশ্রয়", "হে আল্লাহ! আমি কুফর ও দারিদ্র্য থেকে তোমার আশ্রয় চাই এবং কবরের আজাব থেকে তোমার আশ্রয় চাই। তুমি ছাড়া কোনো ইলাহ নেই।", "সকাল-সন্ধ্যা তিনবার।", "আবু বাকরা (রা.) নবী ﷺ-কে এটি পড়তে শুনেছেন।"),
        "dua_sharri_sami" to DuaText("নিজের ইন্দ্রিয়ের অনিষ্ট থেকে আশ্রয়", "হে আল্লাহ! আমি তোমার আশ্রয় চাই আমার কানের অনিষ্ট থেকে, আমার চোখের অনিষ্ট থেকে, আমার জিহ্বার অনিষ্ট থেকে, আমার অন্তরের অনিষ্ট থেকে এবং আমার কামনার অনিষ্ট থেকে।", "শাকাল ইবনে হুমাইদ (রা.)-কে শেখানো।", "অঙ্গ-প্রত্যঙ্গ ও নফসকে গুনাহ থেকে বাঁচানোর দোয়া।"),
        "dua_hadm_gharaq" to DuaText("আকস্মিক মৃত্যু ও দুর্ঘটনা থেকে আশ্রয়", "হে আল্লাহ! আমি তোমার আশ্রয় চাই (ঘর) ধসে পড়া থেকে, উঁচু থেকে পড়া থেকে, ডুবে যাওয়া, পুড়ে যাওয়া ও বার্ধক্য থেকে, মৃত্যুর সময় শয়তানের বিভ্রান্তি থেকে, তোমার পথ থেকে পিঠ ফিরিয়ে মরা থেকে এবং (বিষাক্ত প্রাণীর) দংশনে মরা থেকে।", "দুর্ঘটনা ও মন্দ মৃত্যু থেকে আশ্রয়।", "নবী ﷺ-এর আশ্রয়ের দোয়া।"),
        "dua_ju_khiyanah" to DuaText("ক্ষুধা ও খিয়ানত থেকে আশ্রয়", "হে আল্লাহ! আমি ক্ষুধা থেকে তোমার আশ্রয় চাই, কারণ তা নিকৃষ্ট সঙ্গী, আর খিয়ানত থেকে তোমার আশ্রয় চাই, কারণ তা নিকৃষ্ট অন্তরঙ্গ।", "ক্ষুধা ও খিয়ানত থেকে আশ্রয়।", "নবী ﷺ-এর আশ্রয়ের দোয়া।"),
        "dua_huda_tuqa" to DuaText("হেদায়েত, তাকওয়া, পবিত্রতা ও অমুখাপেক্ষিতা", "হে আল্লাহ! আমি তোমার কাছে হেদায়েত, তাকওয়া, চারিত্রিক পবিত্রতা ও অমুখাপেক্ষিতা চাই।", "নবী ﷺ-এর সংক্ষিপ্ত ব্যাপক দোয়া।", "দ্বীন ও দুনিয়ার চারটি মৌলিক নিয়ামত।"),
        "dua_aslih_li_dini" to DuaText("আমার দ্বীন, দুনিয়া ও আখিরাত ঠিক করো", "হে আল্লাহ! আমার দ্বীন ঠিক করে দাও যা আমার সব কাজের রক্ষাকবচ, আমার দুনিয়া ঠিক করে দাও যাতে আমার জীবিকা, আমার আখিরাত ঠিক করে দাও যেখানে আমাকে ফিরে যেতে হবে। জীবনকে আমার জন্য সব কল্যাণে বৃদ্ধি বানাও এবং মৃত্যুকে সব অকল্যাণ থেকে মুক্তি বানাও।", "দ্বীন, দুনিয়া ও আখিরাত — তিনটিরই সংশোধন।", "নবী ﷺ-এর ব্যাপক দোয়া।"),
        "dua_musarrifal_qulub" to DuaText("আমাদের অন্তর তোমার আনুগত্যে ফেরাও", "হে আল্লাহ, অন্তর পরিবর্তনকারী! আমাদের অন্তরকে তোমার আনুগত্যের দিকে ফিরিয়ে দাও।", "অন্তরকে আনুগত্যে দৃঢ় রাখার দোয়া।", "সব মানুষের অন্তর রহমানের দুই আঙুলের মাঝে।"),
        "dua_jannah_nar" to DuaText("জান্নাত চাওয়া, আগুন থেকে আশ্রয়", "হে আল্লাহ! আমি তোমার কাছে জান্নাত চাই এবং আগুন থেকে তোমার আশ্রয় চাই।", "তাশাহহুদের পর বা যেকোনো সময়।", "নবী ﷺ বলেছেন: আমরাও এর আশেপাশেই দোয়া করি।"),
        "dua_khayri_kullih" to DuaText("সব কল্যাণ, এখন ও পরে", "হে আল্লাহ! আমি তোমার কাছে সব কল্যাণ চাই — তাৎক্ষণিক ও বিলম্বিত, যা জানি ও যা জানি না — আর সব অকল্যাণ থেকে তোমার আশ্রয় চাই — তাৎক্ষণিক ও বিলম্বিত, যা জানি ও যা জানি না। হে আল্লাহ! আমি তোমার কাছে জান্নাত এবং এমন কথা ও কাজ চাই যা তার নিকটবর্তী করে, আর আগুন এবং এমন কথা ও কাজ থেকে আশ্রয় চাই যা তার নিকটবর্তী করে।", "নবী ﷺ আয়েশা (রা.)-কে এই ব্যাপক দোয়া শিখিয়েছেন (দোয়ার অংশ)।", "সব কল্যাণ একত্রকারী দোয়া।"),
        "dua_ihdini_saddidni" to DuaText("আমাকে হেদায়েত দাও ও সঠিক রাখো", "হে আল্লাহ! আমাকে হেদায়েত দাও এবং আমাকে সঠিক পথে অবিচল রাখো।", "নবী ﷺ আলী (রা.)-কে শিখিয়েছেন।", "হেদায়েতকে পথের দিশা এবং সঠিকতাকে তীরের সোজা গতির মতো মনে রাখো।"),
        "dua_hubbaka" to DuaText("আল্লাহর ভালোবাসা চাওয়া", "হে আল্লাহ! আমি তোমার কাছে তোমার ভালোবাসা চাই, এবং যে তোমাকে ভালোবাসে তার ভালোবাসা, এবং এমন আমল যা আমাকে তোমার ভালোবাসায় পৌঁছায়। হে আল্লাহ! তোমার ভালোবাসাকে আমার কাছে আমার প্রাণ, আমার পরিবার ও ঠান্ডা পানির চেয়েও প্রিয় করে দাও।", "দাউদ (আ.)-এর দোয়া যা নবী ﷺ বর্ণনা করেছেন।", "আল্লাহর ভালোবাসা সবচেয়ে বড় সম্পদ।"),
        "dua_filal_khayrat" to DuaText("ভালো কাজ করা ও মন্দ ছাড়া", "হে আল্লাহ! আমি তোমার কাছে ভালো কাজ করা, মন্দ কাজ ছাড়া এবং মিসকিনদের ভালোবাসার তাওফিক চাই, আর চাই তুমি আমাকে ক্ষমা করো ও দয়া করো। আর যখন তুমি কোনো জাতিকে ফিতনায় ফেলতে চাও, তখন আমাকে ফিতনামুক্ত অবস্থায় মৃত্যু দাও। আমি তোমার কাছে তোমার ভালোবাসা, তোমাকে যারা ভালোবাসে তাদের ভালোবাসা এবং এমন আমলের ভালোবাসা চাই যা তোমার ভালোবাসার নিকটবর্তী করে।", "স্বপ্নে আল্লাহ নবী ﷺ-কে এই দোয়া শিখিয়েছেন।", "নবী ﷺ বলেছেন: এটি সত্য, এটি শেখো ও শেখাও।"),
        "dua_bi_ilmikal_ghayb" to DuaText("যতক্ষণ জীবন উত্তম ততক্ষণ বাঁচিয়ে রাখো", "হে আল্লাহ! তোমার অদৃশ্যের জ্ঞান ও সৃষ্টির উপর তোমার ক্ষমতার উসিলায় — যতক্ষণ তোমার জ্ঞানে জীবন আমার জন্য উত্তম, আমাকে বাঁচিয়ে রাখো, আর যখন মৃত্যু উত্তম তখন মৃত্যু দাও। হে আল্লাহ! আমি তোমার কাছে গোপনে ও প্রকাশ্যে তোমার ভয়, সন্তুষ্টি ও রাগে সত্য কথা এবং দারিদ্র্য ও প্রাচুর্যে মধ্যপন্থা চাই।", "আম্মার ইবনে ইয়াসির (রা.)-এর নামাজের দোয়া (শুরুর অংশ)।", "নবী ﷺ নামাজে এই দোয়া করতেন।"),
        "dua_ism_azam_mannan" to DuaText("ইসমে আজম: আল-মান্নান", "হে আল্লাহ! আমি তোমার কাছে প্রার্থনা করি এই উসিলায় যে সকল প্রশংসা তোমার, তুমি ছাড়া কোনো ইলাহ নেই, তুমি মহা অনুগ্রহকারী, আসমান ও জমিনের অভিনব স্রষ্টা। হে মহিমা ও সম্মানের অধিকারী, হে চিরঞ্জীব, হে ধারক!", "নবী ﷺ বলেছেন এই ব্যক্তি ইসমে আজম দিয়ে দোয়া করেছে।", "এই নামে দোয়া করলে কবুল হয়।"),
        "dua_ism_azam_ahad_samad" to DuaText("ইসমে আজম: আল-আহাদ আস-সামাদ", "হে আল্লাহ! আমি তোমার কাছে প্রার্থনা করি এই উসিলায় যে আমি সাক্ষ্য দিচ্ছি তুমিই আল্লাহ, তুমি ছাড়া কোনো ইলাহ নেই, একক, অমুখাপেক্ষী, যিনি কাউকে জন্ম দেননি এবং কারও থেকে জন্ম নেননি, আর তাঁর সমতুল্য কেউ নেই।", "নবী ﷺ বলেছেন সে আল্লাহর কাছে তাঁর ইসমে আজম দিয়ে চেয়েছে।", "এর মাধ্যমে চাইলে দেওয়া হয়, দোয়া করলে কবুল হয়।"),
        "dua_thabbitni_hadiyan" to DuaText("আমাকে অবিচল, হেদায়েতপ্রাপ্ত ও পথপ্রদর্শক বানাও", "হে আল্লাহ! আমাকে অবিচল রাখো এবং আমাকে হেদায়েতদানকারী ও হেদায়েতপ্রাপ্ত বানাও।", "নবী ﷺ জারির (রা.)-এর জন্য এই দোয়া করেছেন (নিজের জন্য 'সাব্বিতনি' বলুন)।", "মূল দোয়া জারির (রা.)-এর জন্য 'সাব্বিতহু' শব্দে।"),
        "dua_rabbighfir_tub_alayya" to DuaText("আমাকে ক্ষমা করো ও তওবা কবুল করো", "হে আমার রব! আমাকে ক্ষমা করো এবং আমার তওবা কবুল করো, নিশ্চয়ই তুমি তওবা কবুলকারী, দয়ালু।", "এক মজলিসে একশ বার — নবী ﷺ-এর আমল।", "সাহাবিরা এক মজলিসে নবী ﷺ-কে একশ বার এটি বলতে গুনেছেন।"),
        "dua_rafiq_ala" to DuaText("মৃত্যুপথযাত্রীর দোয়া", "হে আল্লাহ! আমাকে ক্ষমা করো, আমার প্রতি দয়া করো এবং আমাকে সর্বোচ্চ বন্ধুর সাথে মিলিত করো।", "নবী ﷺ-এর শেষ দোয়া — অসুস্থ ব্যক্তি নিজের জন্য।", "নবী ﷺ ইন্তেকালের সময় এই দোয়া করেছেন।"),
        "dua_la_bas_tahur" to DuaText("অসুস্থকে সান্ত্বনা: পবিত্রতা", "কোনো ক্ষতি নেই, ইনশাআল্লাহ (এই অসুখ গুনাহ থেকে) পবিত্রকারী।", "অসুস্থকে দেখতে গিয়ে সান্ত্বনার জন্য।", "নবী ﷺ অসুস্থের কাছে গেলে এটি বলতেন।"),
        "dua_talqeen" to DuaText("মৃত্যুপথযাত্রীর জন্য তালকিন", "আল্লাহ ছাড়া কোনো ইলাহ নেই।", "মৃত্যুপথযাত্রীর কাছে কালিমা পড়ুন (তাকে জোর করবেন না)।", "যার শেষ কথা 'লা ইলাহা ইল্লাল্লাহ' সে জান্নাতে প্রবেশ করবে (আবু দাউদ ৩১১৬)।"),
        "dua_ahyini_ma_kanat" to DuaText("মৃত্যু কামনার পরিবর্তে", "হে আল্লাহ! যতক্ষণ জীবন আমার জন্য উত্তম, আমাকে বাঁচিয়ে রাখো, আর যখন মৃত্যু আমার জন্য উত্তম, আমাকে মৃত্যু দাও।", "কষ্টে মৃত্যু কামনার পরিবর্তে।", "নবী ﷺ মৃত্যু কামনা নিষেধ করে এটি শিখিয়েছেন।"),
        "dua_for_one_i_cursed" to DuaText("যাকে কথায় কষ্ট দিয়েছি তার জন্য", "হে আল্লাহ! যে মুমিনকেই আমি গালমন্দ করেছি, কিয়ামতের দিন তা তার জন্য তোমার নৈকট্যের মাধ্যম বানিয়ে দাও।", "রাগে কাউকে গালমন্দ করে থাকলে তার জন্য।", "নবী ﷺ-এর দোয়া।"),
        "dua_praising_someone" to DuaText("কারও প্রশংসা করার সময়", "আমি অমুককে এমন মনে করি, আর আল্লাহই তার হিসাবগ্রহণকারী, এবং আমি আল্লাহর সামনে কারও পবিত্রতার দাবি করি না।", "কারও প্রশংসা করতে হলে অতিরঞ্জনের পরিবর্তে।", "নবী ﷺ প্রশংসার এই আদব শিখিয়েছেন।"),
        "dua_being_praised" to DuaText("যখন আপনার প্রশংসা করা হয়", "হে আল্লাহ! তারা যা বলছে তার জন্য আমাকে পাকড়াও করো না, আর আমার সেসব গুনাহ ক্ষমা করো যা তারা জানে না।", "নিজের প্রশংসা শুনে — একজন সাহাবির (রা.) আমল।", "প্রশংসায় অহংকার থেকে বাঁচার উপায়।"),
        "dua_non_muslim_sneezes" to DuaText("অমুসলিম হাঁচি দিলে", "আল্লাহ তোমাকে হেদায়েত দিন এবং তোমার অবস্থা সংশোধন করুন।", "অমুসলিম হাঁচি দিয়ে 'আলহামদুলিল্লাহ' বললে।", "ইহুদিরা নবী ﷺ-এর কাছে হাঁচি দিত যেন তিনি 'ইয়ারহামুকাল্লাহ' বলেন, তখন তিনি এটি বলতেন।"),
        "dua_reply_ahl_kitab_salam" to DuaText("আহলে কিতাবের সালামের জবাব", "আর তোমাদের উপরও।", "আহলে কিতাব সালাম দিলে।", "নবী ﷺ-এর নির্দেশ।"),
        "dua_fasting_invited" to DuaText("রোজায় দাওয়াত পেলে", "আমি রোজাদার।", "রোজা অবস্থায় দাওয়াত পেলে বা কেউ ঝগড়া করলে।", "রোজাদার দাওয়াত কবুল করলে মেজবানের জন্য দোয়া করবে।"),
        "dua_for_who_gave_drink" to DuaText("যে খাইয়েছে-পান করিয়েছে তার জন্য", "হে আল্লাহ! যে আমাকে খাইয়েছে তাকে খাওয়াও, আর যে আমাকে পান করিয়েছে তাকে পান করাও।", "যে খাওয়ায় বা পান করায় তার জন্য।", "নবী ﷺ মিকদাদ (রা.)-এর জন্য এই দোয়া করেছেন।"),
        "dua_eid_greeting" to DuaText("ঈদের শুভেচ্ছা", "আল্লাহ আমাদের ও তোমাদের থেকে (আমল) কবুল করুন।", "ঈদের দিন একে অপরকে — সাহাবায়ে কেরামের (রা.) আমল।", "সাহাবিরা ঈদে সাক্ষাৎ হলে এটি বলতেন।"),
        "dua_wedding_night" to DuaText("বিয়ের পর নববধূর জন্য", "হে আল্লাহ! আমি তোমার কাছে তার কল্যাণ এবং যে স্বভাবে তুমি তাকে সৃষ্টি করেছ তার কল্যাণ চাই, আর তার অনিষ্ট এবং সেই স্বভাবের অনিষ্ট থেকে তোমার আশ্রয় চাই।", "বিয়ের পর স্ত্রীর কপালে হাত রেখে।", "নবী ﷺ-এর শিক্ষা — বিয়েতে বরকত।"),
        "dua_istisqa_ibadak" to DuaText("তোমার বান্দা ও পশুদের পানি দাও", "হে আল্লাহ! তোমার বান্দা ও পশুদের পানি দাও, তোমার রহমত বিস্তৃত করো এবং তোমার মৃত ভূমিকে জীবিত করো।", "বৃষ্টি প্রার্থনা (ইস্তিসকা)।", "নবী ﷺ বৃষ্টির জন্য এই দোয়া করতেন।"),
        "dua_seeing_clouds" to DuaText("কালো মেঘ দেখলে", "হে আল্লাহ! আমি এর অনিষ্ট থেকে তোমার আশ্রয় চাই।", "আকাশে মেঘ দেখে; বৃষ্টি হলে 'আল্লাহুম্মা সাইয়্যিবান নাফিআ'।", "নবী ﷺ মেঘ দেখলে কাজ ছেড়ে এই দোয়া করতেন।"),
        "dua_jamarat" to DuaText("জামারাতে কংকর নিক্ষেপ", "আল্লাহ সবচেয়ে বড়।", "প্রতিটি কংকর নিক্ষেপের সময়।", "নবী ﷺ প্রতিটি কংকরের সাথে তাকবির বলতেন, তারপর প্রথম ও দ্বিতীয় জামরার পর কিবলামুখী হয়ে দীর্ঘ দোয়া করতেন।"),
        "dua_rabbi_ainni" to DuaText("হে আমার রব, আমাকে সাহায্য করো, আমার বিরুদ্ধে নয়", "হে আমার রব! আমাকে সাহায্য করো, আমার বিরুদ্ধে সাহায্য করো না, আমাকে বিজয় দাও, আমার উপর বিজয় দিও না, আমার পক্ষে কৌশল করো, আমার বিরুদ্ধে কৌশল করো না, আমাকে হেদায়েত দাও ও হেদায়েত আমার জন্য সহজ করো, আর যে আমার উপর জুলুম করে তার বিরুদ্ধে আমাকে সাহায্য করো।", "নবী ﷺ-এর ব্যাপক দোয়া (শুরুর অংশ)।", "দুনিয়া ও দ্বীনের সব সাহায্য একত্রকারী দোয়া।"),
        "dua_ati_nafsi_taqwaha" to DuaText("আমার নফসকে তার তাকওয়া দাও", "হে আল্লাহ! আমার নফসকে তার তাকওয়া দান করো এবং তাকে পবিত্র করো, তুমিই তাকে সর্বোত্তম পবিত্রকারী, তুমিই তার অভিভাবক ও মালিক।", "নফসের সংশোধন ও পরিশুদ্ধির জন্য।", "নবী ﷺ এই দোয়া করতেন।"),
        "dua_iqsim_lana_khashyatik" to DuaText("আমাদের এমন ভয় দান করো", "হে আল্লাহ! আমাদের তোমার এতটুকু ভয় দাও যা আমাদের ও তোমার অবাধ্যতার মাঝে আড়াল হয়, এতটুকু আনুগত্য যা আমাদের তোমার জান্নাতে পৌঁছায়, এবং এতটুকু ইয়াকিন যা দুনিয়ার বিপদ আমাদের জন্য সহজ করে। যতদিন বাঁচিয়ে রাখো আমাদের কান, চোখ ও শক্তি দিয়ে উপকৃত করো এবং তা আমাদের উত্তরাধিকারী বানাও। যে আমাদের উপর জুলুম করে তার থেকে প্রতিশোধ নাও, শত্রুদের বিরুদ্ধে আমাদের সাহায্য করো, আমাদের বিপদ আমাদের দ্বীনে দিও না, দুনিয়াকে আমাদের সবচেয়ে বড় চিন্তা ও জ্ঞানের শেষ সীমা বানিও না, এবং আমাদের উপর এমন কাউকে চাপিয়ে দিও না যে আমাদের প্রতি দয়া করবে না।", "মজলিস থেকে ওঠার সময় — নবী ﷺ প্রায় এই দোয়া না করে উঠতেন না।", "দ্বীন, দুনিয়া ও আখিরাতের কল্যাণের ব্যাপক দোয়া।"),
        "dua_infani_bima_allamtani" to DuaText("যা শিখিয়েছ তা দিয়ে উপকৃত করো", "হে আল্লাহ! তুমি আমাকে যা শিখিয়েছ তা দিয়ে আমাকে উপকৃত করো, আমাকে তা শেখাও যা আমার উপকারে আসে এবং আমার জ্ঞান বৃদ্ধি করো।", "জ্ঞান অর্জনের সময় বা পড়াশোনার আগে।", "উপকারী জ্ঞান ও তার উপর আমলের দোয়া।"),
        "dua_jar_su" to DuaText("খারাপ প্রতিবেশী থেকে আশ্রয়", "হে আল্লাহ! আমি স্থায়ী বাসস্থানের খারাপ প্রতিবেশী থেকে তোমার আশ্রয় চাই, কারণ সফরের প্রতিবেশী তো বদলে যায়।", "খারাপ প্রতিবেশী থেকে হেফাজতের জন্য।", "নবী ﷺ এ থেকে আশ্রয় চাওয়ার আদেশ দিয়েছেন।"),
        "dua_ishfi_abdak" to DuaText("অসুস্থের আরোগ্যের জন্য", "হে আল্লাহ! তোমার বান্দাকে আরোগ্য দাও যেন সে তোমার জন্য শত্রুর মোকাবেলা করে বা তোমার জন্য নামাজের দিকে হেঁটে যায়।", "অসুস্থকে দেখতে গিয়ে তার জন্য।", "নবী ﷺ অসুস্থের জন্য এটি বলা শিখিয়েছেন।"),
        "dua_la_mania" to DuaText("তুমি যা দাও কেউ তা আটকাতে পারে না", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই, রাজত্ব ও প্রশংসা তাঁরই এবং তিনি সব কিছুর উপর ক্ষমতাবান। হে আল্লাহ! তুমি যা দাও তা কেউ আটকাতে পারে না, আর তুমি যা আটকাও তা কেউ দিতে পারে না, আর কোনো ধনীর ধন তোমার বিপরীতে কাজে আসে না।", "ফরজ নামাজের সালামের পর।", "নবী ﷺ প্রত্যেক ফরজ নামাজের পর এটি বলতেন।"),
        "dua_slaughtering" to DuaText("পশু জবাইয়ের সময়", "আল্লাহর নামে, আর আল্লাহ সবচেয়ে বড়।", "কুরবানি বা জবাইয়ের সময়।", "নবী ﷺ কুরবানির সময় বিসমিল্লাহ ও তাকবির বলেছেন।"),
        "dua_undressing" to DuaText("কাপড় খোলার সময়", "আল্লাহর নামে।", "কাপড় খোলার সময় (গোসল বা কাপড় বদলানোর সময়)।", "জিনের দৃষ্টি ও মানুষের সতরের মাঝে পর্দা হয়ে যায়।"),
        "dua_ilbas_jadidan" to DuaText("কাউকে নতুন কাপড়ে দেখলে", "নতুন পরো, প্রশংসনীয় জীবন যাপন করো এবং শহিদ হয়ে মৃত্যুবরণ করো।", "কোনো মুসলিম ভাইকে নতুন কাপড়ে দেখে।", "নবী ﷺ উমর (রা.)-কে নতুন কাপড়ে দেখে এই দোয়া দিয়েছেন।"),
        "dua_hajj_la_riya" to DuaText("লোকদেখানো মুক্ত হজ", "হে আল্লাহ! এমন হজ যাতে লোকদেখানো নেই, খ্যাতির আকাঙ্ক্ষাও নেই।", "হজের নিয়তের সময় ইখলাসের জন্য।", "নবী ﷺ হজের সময় এই দোয়া করেছেন।"),
        "dua_q_muslimayni_laka" to DuaText("আমাদের আত্মসমর্পণকারী বানাও (ইবরাহিম ও ইসমাইল আ.)", "হে আমাদের রব! আমাদের দুজনকে তোমার আত্মসমর্পণকারী বানাও এবং আমাদের বংশধরদের মধ্য থেকেও একটি উম্মত তোমার আত্মসমর্পণকারী বানাও, আমাদের ইবাদতের পদ্ধতি দেখিয়ে দাও এবং আমাদের তওবা কবুল করো, নিশ্চয়ই তুমি তওবা কবুলকারী, দয়ালু।", "নিজের ও সন্তানদের আনুগত্যের দোয়া।", "কাবা নির্মাণের সময়ের দোয়া।"),
        "dua_q_iftah_baynana" to DuaText("আমাদের মাঝে ফয়সালা করো (শুআইব আ.)", "হে আমাদের রব! আমাদের ও আমাদের সম্প্রদায়ের মাঝে সত্যের সাথে ফয়সালা করে দাও, আর তুমিই শ্রেষ্ঠ ফয়সালাকারী।", "সত্য ও মিথ্যার মাঝে ফয়সালার জন্য।", "সম্প্রদায় অস্বীকার করলে শুআইব (আ.)-এর দোয়া।"),
        "dua_q_la_akuna_zahiran" to DuaText("কখনো অপরাধীদের সাহায্যকারী নই (মুসা আ.)", "হে আমার রব! তুমি আমার প্রতি যে অনুগ্রহ করেছ তার কারণে আমি কখনো অপরাধীদের সাহায্যকারী হব না।", "আল্লাহর নিয়ামতের শুকরিয়া ও অপরাধীদের সাহায্য না করার অঙ্গীকার।", "তওবার পর মুসা (আ.)-এর অঙ্গীকার।"),
        "dua_q_nuh_unsurni" to DuaText("আমাকে সাহায্য করো, তারা আমাকে মিথ্যাবাদী বলেছে (নূহ আ.)", "হে আমার রব! আমাকে সাহায্য করো, কারণ তারা আমাকে মিথ্যাবাদী বলেছে।", "যখন লোকেরা মিথ্যাবাদী বলে ও সত্য মানে না।", "নূহ (আ.)-এর দোয়া যা কবুল হয়েছে।"),
        "dua_q_ihkum_bil_haqq" to DuaText("হে আমার রব, সত্যের সাথে ফয়সালা করো", "হে আমার রব! সত্যের সাথে ফয়সালা করো। আর আমাদের রব পরম করুণাময়, তোমরা যা রচনা করো তার বিরুদ্ধে তাঁরই সাহায্য চাওয়া হয়।", "মিথ্যা কথা ও অভিযোগের মোকাবেলায়।", "নবী ﷺ-কে শেখানো দোয়া।"),
        "dua_ghalabatid_dayn" to DuaText("ভারী ঋণ ও শত্রু থেকে আশ্রয়", "হে আল্লাহ! আমি ঋণের চাপ, শত্রুর আধিপত্য এবং শত্রুদের উল্লাস থেকে তোমার আশ্রয় চাই।", "ঋণের বোঝা ও শত্রুর আধিপত্য থেকে হেফাজত।", "নবী ﷺ এসব থেকে আশ্রয় চাইতেন।"),
        "dua_faqr_qillah_dhillah" to DuaText("দারিদ্র্য ও অপমান থেকে আশ্রয়", "হে আল্লাহ! আমি দারিদ্র্য, স্বল্পতা ও অপমান থেকে তোমার আশ্রয় চাই, এবং জুলুম করা বা জুলুমের শিকার হওয়া থেকে।", "অভাব, স্বল্পতা ও অপমান থেকে বাঁচতে।", "নবী ﷺ-এর শেখানো আশ্রয়।"),
        "dua_five_things_new_muslim" to DuaText("ক্ষমা, দয়া, হেদায়েত, নিরাপত্তা, রিজিক", "হে আল্লাহ! আমাকে ক্ষমা করো, আমার প্রতি দয়া করো, আমাকে হেদায়েত দাও, আমাকে নিরাপত্তা দাও এবং আমাকে রিজিক দাও।", "নবী ﷺ নতুন মুসলিমকে নামাজের সাথে এই দোয়া শেখাতেন।", "নবী ﷺ বলেছেন: এই বাক্যগুলো তোমার জন্য দুনিয়া ও আখিরাত একত্র করে।"),
        "dua_ruku_laka_raka_tu" to DuaText("রুকুতে — তোমার জন্য রুকু করলাম", "হে আল্লাহ! আমি তোমার জন্য রুকু করলাম, তোমার উপর ঈমান আনলাম এবং তোমার কাছে আত্মসমর্পণ করলাম। আমার কান, চোখ, মস্তিষ্ক, হাড় ও শিরা তোমার সামনে বিনত হলো।", "রুকুতে (বিশেষত নফল নামাজে)।", "নবী ﷺ রুকুতে এটি পড়তেন।"),
        "dua_sujood_laka_sajadtu" to DuaText("সিজদায় — তোমাকে সিজদা করলাম", "হে আল্লাহ! আমি তোমাকে সিজদা করলাম, তোমার উপর ঈমান আনলাম এবং তোমার কাছে আত্মসমর্পণ করলাম। আমার চেহারা সিজদা করল সেই সত্তাকে যিনি একে সৃষ্টি করেছেন, আকৃতি দিয়েছেন এবং এর কান ও চোখ খুলে দিয়েছেন। বরকতময় আল্লাহ, সর্বোত্তম স্রষ্টা।", "সিজদায় (বিশেষত নফল নামাজে)।", "নবী ﷺ সিজদায় এটি পড়তেন।"),
        "dua_ruku_sujood_subhanaka" to DuaText("হে আমাদের রব, তুমি পবিত্র — আমাকে ক্ষমা করো", "হে আল্লাহ, আমাদের রব! তুমি পবিত্র, তোমার প্রশংসার সাথে। হে আল্লাহ! আমাকে ক্ষমা করো।", "রুকু ও সিজদায়।", "আয়েশা (রা.): নবী ﷺ রুকু ও সিজদায় বেশি বেশি এটি পড়তেন।"),
        "dua_q_musa_li_akhi" to DuaText("আমাকে ও আমার ভাইকে ক্ষমা করো (মুসা আ.)", "হে আমার রব! আমাকে ও আমার ভাইকে ক্ষমা করো এবং আমাদের তোমার রহমতে প্রবেশ করাও, আর তুমি দয়ালুদের মধ্যে সর্বশ্রেষ্ঠ দয়ালু।", "নিজের ও ভাই/প্রিয়জনদের জন্য ক্ষমা।", "হারুন (আ.)-এর জন্য মুসা (আ.)-এর দোয়া।"),
        "dua_q_ufawwidu_amri" to DuaText("আমি আমার বিষয় আল্লাহর কাছে সোপর্দ করছি", "আর আমি আমার বিষয় আল্লাহর কাছে সোপর্দ করছি, নিশ্চয়ই আল্লাহ বান্দাদের সম্যক দ্রষ্টা।", "যখন লোকেরা বিরোধিতা করে এবং বিষয়টি আল্লাহর কাছে সোপর্দ করতে হয়।", "ফেরাউনের সম্প্রদায়ের মুমিনের উক্তি; এরপর আল্লাহ তাকে তাদের চক্রান্ত থেকে রক্ষা করেন।"),
        "dua_q_hawariyyun" to DuaText("হাওয়ারিদের দোয়া — আমাদের সাক্ষীদের সাথে লেখো", "হে আমাদের রব! তুমি যা নাজিল করেছ আমরা তাতে ঈমান এনেছি এবং রাসুলের অনুসরণ করেছি, অতএব আমাদের সাক্ষ্যদাতাদের সাথে লিখে নাও।", "ঈমান ও রাসুলের অনুসরণে অবিচলতার জন্য।", "ঈসা (আ.)-এর হাওয়ারিদের দোয়া।"),
        "dua_q_la_tukhzini" to DuaText("আমাকে লাঞ্ছিত করো না (ইবরাহিম আ.)", "আর যেদিন মানুষকে পুনরুত্থিত করা হবে সেদিন আমাকে লাঞ্ছিত করো না।", "কিয়ামতের লাঞ্ছনা থেকে বাঁচতে।", "আখিরাতের জন্য ইবরাহিম (আ.)-এর দোয়া।"),
        "dua_iftar_laka_sumtu" to DuaText("ইফতার — তোমার জন্য রোজা রেখেছি", "হে আল্লাহ! আমি তোমার জন্য রোজা রেখেছি এবং তোমারই রিজিক দিয়ে ইফতার করছি।", "রোজা খোলার সময় (ইফতারের প্রসিদ্ধ দোয়া)।", "নবী ﷺ ইফতারের সময় এটি বলতেন। এটি মুরসাল বর্ণনা যা অন্য বর্ণনা দ্বারা শক্তিশালী; হানাফি ও অধিকাংশ আলেমের কাছে ইফতারে এটি পড়া প্রচলিত।"),
        "dua_iftar_ibn_umar" to DuaText("ইফতার — তোমার বিশাল রহমতে আমাকে ক্ষমা করো", "হে আল্লাহ! আমি তোমার সেই রহমতের উসিলায় যা সব কিছুকে পরিবেষ্টন করে আছে, তোমার কাছে প্রার্থনা করি যেন আমাকে ক্ষমা করো।", "ইফতারের সময় — আব্দুল্লাহ ইবনে আমর (রা.) এই দোয়া করতেন; ইফতারে রোজাদারের দোয়া ফেরানো হয় না।", "হাদিস: ইফতারের সময় রোজাদারের দোয়া ফেরানো হয় না।"),
        "dua_inni_saim" to DuaText("রোজায় কেউ উসকানি দিলে", "আমি রোজাদার, আমি রোজাদার।", "রোজা অবস্থায় কেউ গালি দিলে বা ঝগড়া করলে।", "নবী ﷺ বলেছেন: রোজা ঢাল, তাই রোজাদার অশ্লীল কথা বা মূর্খতা করবে না — কেউ ঝগড়া করলে দুবার এটি বলবে।"),
        "dua_eid_takbeer" to DuaText("ঈদগাহে যাওয়ার সময় তাকবির", "আল্লাহ সবচেয়ে বড়, আল্লাহ সবচেয়ে বড়, আল্লাহ ছাড়া কোনো ইলাহ নেই, আর আল্লাহ সবচেয়ে বড়, আল্লাহ সবচেয়ে বড়, আর সকল প্রশংসা আল্লাহরই।", "চাঁদরাত থেকে ঈদুল ফিতরের নামাজ পর্যন্ত, বিশেষত ঈদগাহে যাওয়ার সময়।", "কুরআনের নির্দেশ: 'যাতে তোমরা সংখ্যা পূর্ণ করো এবং আল্লাহর মহত্ত্ব ঘোষণা করো' (আল-বাকারা ২:১৮৫)। ইবনে মাসউদ (রা.) এই তাকবির বলতেন।"),
        "dua_ahsin_aqibatana" to DuaText("সব কাজে আমাদের পরিণাম সুন্দর করো", "হে আল্লাহ! সব কাজে আমাদের পরিণাম সুন্দর করো এবং আমাদের দুনিয়ার লাঞ্ছনা ও আখিরাতের আজাব থেকে রক্ষা করো।", "প্রতিটি কাজের সুন্দর পরিণামের জন্য।", "যে এই দোয়া করে এবং পরীক্ষার আগে মারা যায়, সে (ফিতনা থেকে নিরাপদ অবস্থায়) মারা যায়।"),
        "dua_fadlika_wa_rahmatik" to DuaText("তোমার অনুগ্রহ ও রহমত চাই", "হে আল্লাহ! আমি তোমার কাছে তোমার অনুগ্রহ ও রহমত চাই, কারণ এগুলোর মালিক তুমি ছাড়া কেউ নেই।", "রিজিক ও রহমত চাওয়ার সময়।", "নবী ﷺ-এর কাছে মেহমান এলো কিন্তু খাবার ছিল না, তিনি এই দোয়া করলেন, তারপর উপহার এলো।"),
        "dua_allahu_akbar_kabira_2696" to DuaText("এক বেদুইনকে শেখানো বাক্য", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই। আল্লাহ সবচেয়ে বড়, অতি বড়; আল্লাহর জন্য অনেক প্রশংসা; জগতসমূহের রব আল্লাহ পবিত্র; আর পরাক্রমশালী, প্রজ্ঞাময় আল্লাহ ছাড়া কোনো শক্তি ও ক্ষমতা নেই।", "জিকির ও দোয়ার ব্যাপক বাক্য — এক বেদুইনকে শেখানো।", "এরপর 'আল্লাহুম্মাগফিরলি ওয়ারহামনি ওয়াহদিনি ওয়ারযুকনি' বলার শিক্ষা দেন।"),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("আগের ও পরের গুনাহ ক্ষমা করো", "হে আল্লাহ! আমার সেসব গুনাহ ক্ষমা করো যা আমি আগে করেছি ও পরে করেছি, গোপনে করেছি ও প্রকাশ্যে করেছি, যা বাড়াবাড়ি করেছি এবং যা তুমি আমার চেয়ে বেশি জানো। তুমিই অগ্রসরকারী, তুমিই পশ্চাৎকারী, তুমি ছাড়া কোনো ইলাহ নেই।", "তাশাহহুদ ও দরুদের পর সালামের আগে।", "নবী ﷺ নামাজের শেষে তাশাহহুদ ও সালামের মাঝে এটি পড়তেন।"),
        "dua_jiddi_wa_hazli" to DuaText("গুরুত্বে ও ঠাট্টায় করা গুনাহ ক্ষমা করো", "হে আল্লাহ! আমার সেসব গুনাহ ক্ষমা করো যা গুরুত্বের সাথে ও ঠাট্টায় হয়েছে, ভুলে ও ইচ্ছাকৃতভাবে হয়েছে — আর এসবই আমার মধ্যে আছে।", "জানা-অজানা সব ধরনের গুনাহের ক্ষমা।", "নবী ﷺ-এর ব্যাপক ইস্তিগফার।"),
        "dua_rising_ruku_mil" to DuaText("রুকুর পর — আসমানভরা প্রশংসা", "হে আমাদের রব! সকল প্রশংসা তোমারই, আসমানভরা, জমিনভরা এবং এরপর তুমি যা চাও তা ভরা।", "রুকু থেকে উঠে 'রাব্বানা লাকাল হামদ'-এর সাথে।", "নবী ﷺ রুকু থেকে উঠে এটি বলতেন।"),
        "dua_istiftah_kabira" to DuaText("আল্লাহ মহান, অনেক প্রশংসা", "আল্লাহ সবচেয়ে বড়, অতি বড়; আল্লাহর জন্য অনেক প্রশংসা; আর সকাল-সন্ধ্যা আল্লাহর পবিত্রতা।", "নামাজ শুরুর সময় (সানার একটি রূপ)।", "নবী ﷺ বলেছেন: এর জন্য আসমানের দরজা খুলে দেওয়া হয়েছে।"),
        "dua_q_ashku_bathhi" to DuaText("আমি শুধু আল্লাহর কাছে অভিযোগ করি (ইয়াকুব আ.)", "আমি আমার দুঃখ ও বেদনার অভিযোগ শুধু আল্লাহর কাছে করি।", "গভীর দুঃখ ও বিচ্ছেদের সময়।", "ইয়াকুব (আ.) ইউসুফ (আ.)-এর বিচ্ছেদে এটি বলেছিলেন।"),
        "dua_q_khayrun_hafiza" to DuaText("আল্লাহই শ্রেষ্ঠ রক্ষাকারী", "আল্লাহই শ্রেষ্ঠ রক্ষাকারী, এবং তিনি দয়ালুদের মধ্যে সর্বশ্রেষ্ঠ দয়ালু।", "সন্তান বা প্রিয়জনকে সফরে পাঠানোর সময়।", "ইয়াকুব (আ.) তাঁর ছেলেকে আল্লাহর কাছে সোপর্দ করে এটি বলেছিলেন।"),
        "dua_q_aqraba_rashada" to DuaText("আমার রব আমাকে কল্যাণের নিকটতর পথ দেখাবেন", "আশা করি আমার রব আমাকে এর চেয়েও কল্যাণের নিকটতর পথ দেখাবেন।", "কোনো কাজে উত্তম পথের সন্ধান করলে।", "ভুলে গেলে এটি বলার জন্য নবী ﷺ-কে শিক্ষা দেওয়া হয়েছে।"),
        "dua_q_sawa_as_sabil" to DuaText("আমাকে সরল পথ দেখাও (মুসা আ.)", "আশা করি আমার রব আমাকে সরল পথ দেখাবেন।", "নতুন সফর বা অচেনা পথে চলার সময়।", "মাদইয়ানের দিকে রওনা হয়ে মুসা (আ.) এটি বলেছিলেন।"),
        "dua_q_not_among_wrongdoers" to DuaText("আমাকে জালিমদের অন্তর্ভুক্ত করো না", "হে আমার রব! আমাকে জালিম সম্প্রদায়ের অন্তর্ভুক্ত করো না।", "জালিমদের থেকে আলাদা রাখার জন্য আল্লাহর কাছে দোয়া।"),
        "dua_q_do_not_make_us_trial" to DuaText("আমাদের পরীক্ষার বস্তু বানিও না", "হে আমাদের রব! আমাদের কাফিরদের জন্য পরীক্ষার বস্তু বানিও না এবং আমাদের ক্ষমা করো, হে আমাদের রব! নিশ্চয়ই তুমি পরাক্রমশালী, প্রজ্ঞাময়।", "ইবরাহিম (আ.) ও তাঁর সঙ্গীদের দোয়া।"),
        "dua_morning_witness" to DuaText("সকালে তাওহিদের সাক্ষ্য", "হে আল্লাহ! আমি সকালে উপনীত হয়েছি, তোমাকে, তোমার আরশবাহীদের, তোমার ফেরেশতাদের এবং তোমার সমস্ত সৃষ্টিকে সাক্ষী রাখছি যে তুমিই আল্লাহ, তুমি ছাড়া কোনো ইলাহ নেই, তুমি একক, তোমার কোনো শরিক নেই, এবং মুহাম্মাদ ﷺ তোমার বান্দা ও রাসুল।", "বর্ণনায় সকালে চারবার পড়ার কথা এসেছে।"),
        "dua_evening_witness" to DuaText("সন্ধ্যায় তাওহিদের সাক্ষ্য", "হে আল্লাহ! আমি সন্ধ্যায় উপনীত হয়েছি, তোমাকে, তোমার আরশবাহীদের, তোমার ফেরেশতাদের এবং তোমার সমস্ত সৃষ্টিকে সাক্ষী রাখছি যে তুমিই আল্লাহ, তুমি ছাড়া কোনো ইলাহ নেই, তুমি একক, তোমার কোনো শরিক নেই, এবং মুহাম্মাদ ﷺ তোমার বান্দা ও রাসুল।", "বর্ণনায় সন্ধ্যায় চারবার পড়ার কথা এসেছে।"),
        "dua_morning_blessing" to DuaText("সকালে নিয়ামতের শুকরিয়া", "হে আল্লাহ! সকালে আমি বা তোমার কোনো সৃষ্টি যে নিয়ামতই পেয়েছে তা শুধু তোমারই পক্ষ থেকে, তোমার কোনো শরিক নেই; অতএব সকল প্রশংসা ও শুকরিয়া তোমারই।", "সকালে আল্লাহর নিয়ামতের জন্য শুকরিয়ার জিকির।"),
        "dua_evening_blessing" to DuaText("সন্ধ্যায় নিয়ামতের শুকরিয়া", "হে আল্লাহ! সন্ধ্যায় আমি বা তোমার কোনো সৃষ্টি যে নিয়ামতই পেয়েছে তা শুধু তোমারই পক্ষ থেকে, তোমার কোনো শরিক নেই; অতএব সকল প্রশংসা ও শুকরিয়া তোমারই।", "সন্ধ্যায় আল্লাহর নিয়ামতের জন্য শুকরিয়ার জিকির।"),
    )
}
